"""Tests for the dataset correlation figure (evolution_strategy/plot_datasets.py)."""

import logging
import statistics

import pytest

from evolution_strategy import plot_datasets
from evolution_strategy.results import PORTFOLIOS

PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"
SIZES = {"port1": 31, "port2": 85, "port3": 89, "port4": 98, "port5": 225}


@pytest.mark.parametrize("dataset", plot_datasets.DATASETS)
def test_pairwise_correlations_count_each_pair_once(dataset):
    n = SIZES[dataset]
    values = plot_datasets.pairwise_correlations(PORTFOLIOS[dataset])
    assert len(values) == n * (n - 1) // 2
    assert all(-1.0 <= value <= 1.0 for value in values)


def test_correlation_matrix_is_symmetric_with_unit_diagonal():
    matrix = plot_datasets.correlation_matrix(PORTFOLIOS["port1"])
    n = len(matrix)
    assert n == 31
    assert all(matrix[i][i] == 1.0 for i in range(n))
    assert all(matrix[i][j] == matrix[j][i] for i in range(n) for j in range(n))


def test_matrix_matches_the_raw_file():
    # port1.txt records "1 2 .562289" and "1 3 .746125" (1-based company ids).
    matrix = plot_datasets.correlation_matrix(PORTFOLIOS["port1"])
    assert matrix[0][1] == pytest.approx(0.562289)
    assert matrix[2][0] == pytest.approx(0.746125)


@pytest.mark.parametrize(
    "dataset, expected_mean",
    [("port1", 0.527), ("port2", 0.207), ("port3", 0.248), ("port4", 0.163), ("port5", 0.476)],
)
def test_mean_pairwise_correlation(dataset, expected_mean):
    # These rounded means are the ones quoted in the group's notes for section 4.2.
    values = plot_datasets.pairwise_correlations(PORTFOLIOS[dataset])
    assert statistics.fmean(values) == pytest.approx(expected_mean, abs=5e-4)


def test_figure_is_written_as_png(tmp_path):
    out = plot_datasets.plot_dataset_correlations(PORTFOLIOS, tmp_path / "figure.png")
    assert out == tmp_path / "figure.png"
    assert out.read_bytes()[:8] == PNG_SIGNATURE
    assert out.stat().st_size > 10_000


def test_unknown_heatmap_dataset_is_rejected(tmp_path):
    with pytest.raises(ValueError):
        plot_datasets.plot_dataset_correlations(PORTFOLIOS, tmp_path / "x.png", "port9")


def test_cli_writes_the_default_file_name(tmp_path, caplog):
    with caplog.at_level(logging.INFO):
        plot_datasets.main(["--out-dir", str(tmp_path)])
    assert (tmp_path / plot_datasets.FIGURE_NAME).is_file()
    assert "no optimization was run" in caplog.text
